class ListNode {
  constructor(val) {
    this.val = val;
    this.next = null;
  }
}

// Collect all values, then rebuild sorted (a min-heap of k heads is the
// classic O(N log k) approach; shown simply here for the reference view).
function mergeKLists(lists) {
  const values = [];
  for (const head of lists) {
    for (let n = head; n; n = n.next) values.push(n.val);
  }
  values.sort((a, b) => a - b);
  const dummy = new ListNode(0);
  let tail = dummy;
  for (const v of values) { tail.next = new ListNode(v); tail = tail.next; }
  return dummy.next;
}

function build(arr) {
  const dummy = new ListNode(0);
  let tail = dummy;
  for (const v of arr) { tail.next = new ListNode(v); tail = tail.next; }
  return dummy.next;
}
const merged = mergeKLists([build([1, 4, 5]), build([1, 3, 4]), build([2, 6])]);
const out = [];
for (let n = merged; n; n = n.next) out.push(n.val);
console.log(out.join(' '));

